<template>
  <view class="page">
    <text class="title">完善个人信息</text>
    <text class="subtitle">让我们更好地认识你</text>

    <!-- 头像选择 -->
    <button class="avatar-btn" open-type="chooseAvatar" @chooseavatar="onChooseAvatar">
      <image class="avatar" :src="avatarUrl || '/static/logo.png'" mode="aspectFill" />
      <view class="avatar-badge">
        <uni-icons type="camera" size="18" color="#fff" />
      </view>
      <text class="avatar-tip">点击选择头像</text>
    </button>

    <!-- 昵称输入 -->
    <view class="input-wrap">
      <text class="input-label">昵称</text>
      <input
        class="nickname-input"
        type="nickname"
        :value="nickname"
        placeholder="请输入昵称"
        placeholder-class="input-placeholder"
        @change="onNicknameChange"
      />
    </view>

    <!-- 提交按钮 -->
    <view class="btn-wrap">
      <button class="submit-btn" :disabled="!canSubmit || loading" @click="handleSubmit">
        <text class="submit-text">{{ loading ? '保存中...' : '完成' }}</text>
      </button>
      <text class="skip-btn" @click="skip">跳过</text>
    </view>
  </view>
</template>

<script>
import { updateUserProfile } from '@/utils/request.js'

export default {
  data() {
    return {
      avatarUrl: '',
      nickname: '',
      loading: false
    }
  },
  computed: {
    canSubmit() {
      return this.nickname.trim().length > 0
    }
  },
  methods: {
    onChooseAvatar(e) {
      this.avatarUrl = e.detail.avatarUrl
      console.log('[完善信息] 选择头像:', this.avatarUrl)
    },
    onNicknameChange(e) {
      this.nickname = e.detail.value
    },
    async handleSubmit() {
      if (!this.canSubmit) return
      this.loading = true
      try {
        await updateUserProfile({
          nickname: this.nickname,
          avatarUrl: this.avatarUrl
        })
        // 保存到本地
        uni.setStorageSync('userInfo', {
          nickname: this.nickname,
          avatarUrl: this.avatarUrl
        })
        console.log('[完善信息] 保存成功')
        this.goHome()
      } catch (e) {
        console.error('[完善信息] 保存失败:', e)
        // 保存失败也进入首页，本地先存着
        uni.setStorageSync('userInfo', {
          nickname: this.nickname,
          avatarUrl: this.avatarUrl
        })
        this.goHome()
      } finally {
        this.loading = false
      }
    },
    skip() {
      this.goHome()
    },
    goHome() {
      uni.reLaunch({ url: '/pages/index/index' })
    }
  }
}
</script>

<style lang="scss">
$green: #2a6e44;
$bg:    #f8f5ee;
$gray:  #888;

.page {
  min-height: 100vh;
  background: $bg;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 120rpx 48rpx 60rpx;
}

.title {
  font-size: 48rpx;
  font-weight: 700;
  color: #1a1a1a;
  margin-bottom: 16rpx;
}

.subtitle {
  font-size: 26rpx;
  color: $gray;
  margin-bottom: 80rpx;
}

/* 头像 */
.avatar-btn {
  position: relative;
  width: 180rpx;
  height: 180rpx;
  border-radius: 50%;
  padding: 0;
  background: transparent;
  border: none;
  margin-bottom: 16rpx;

  &::after { border: none; }

  .avatar {
    width: 180rpx;
    height: 180rpx;
    border-radius: 50%;
    border: 4rpx solid #e0d8c8;
  }

  .avatar-badge {
    position: absolute;
    bottom: 0; right: 0;
    width: 52rpx; height: 52rpx;
    border-radius: 50%;
    background: $green;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .avatar-tip {
    position: absolute;
    bottom: -40rpx;
    left: 50%;
    transform: translateX(-50%);
    font-size: 22rpx;
    color: $gray;
    white-space: nowrap;
  }
}

/* 昵称输入 */
.input-wrap {
  width: 100%;
  margin-top: 60rpx;
  margin-bottom: 60rpx;

  .input-label {
    display: block;
    font-size: 28rpx;
    color: #1a1a1a;
    margin-bottom: 16rpx;
  }

  .nickname-input {
    width: 100%;
    height: 96rpx;
    background: #fff;
    border-radius: 24rpx;
    padding: 0 32rpx;
    font-size: 32rpx;
    color: #1a1a1a;
  }

  .input-placeholder {
    color: #ccc;
  }
}

/* 按钮 */
.btn-wrap {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 24rpx;

  .submit-btn {
    width: 100%;
    height: 96rpx;
    background: $green;
    border-radius: 50rpx;
    display: flex;
    align-items: center;
    justify-content: center;
    border: none;

    &::after { border: none; }

    &[disabled] {
      background: #ccc;
    }

    .submit-text {
      font-size: 32rpx;
      font-weight: 600;
      color: #fff;
      letter-spacing: 4rpx;
    }
  }

  .skip-btn {
    font-size: 28rpx;
    color: $gray;
  }
}
</style>
